def page(name, title, description, content):
    content = content.replace('width="1536" height="1024"', 'width="1672" height="941"')
    content = content.replace('<form id="enquiry-form">', '<noscript><p>Please use the phone, email or WhatsApp links on this page to enquire. Message preparation requires JavaScript.</p></noscript><form id="enquiry-form">')
    extra_scripts = '<script src="assets/js/packages-data.js" defer></script><script src="assets/js/packages.js" defer></script>' if name == 'packages.html' else ''
    doc = f'''<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><meta name="description" content="{e(description)}"><meta name="theme-color" content="#242424"><title>{e(title)} | Time Cable Vision</title><link rel="icon" href="assets/images/tcv-supplied-logo.png" type="image/png"><link rel="stylesheet" href="assets/css/style.css"><script src="assets/js/site.js" defer></script>{extra_scripts}<meta property="og:title" content="{e(title)} | Time Cable Vision"><meta property="og:description" content="{e(description)}"><meta property="og:type" content="website"><meta property="og:image" content="https://timecablevision.in/assets/images/connected-home.png"><link rel="canonical" href="https://timecablevision.in/{'' if name=='index.html' else name}"></head><body data-page="{name}">{header(name)}<main id="main">{content}</main>{footer()}</body></html>'''
    (ROOT / name).write_text(doc, encoding='utf-8')

def intro(kicker, title, desc):
    return f'<section class="page-intro container"><p class="eyebrow">{e(kicker)}</p><h1>{title}</h1><p class="intro-copy">{e(desc)}</p></section>'

