def slug(name):
    return ''.join(c.lower() if c.isalnum() else '-' for c in name).strip('-').replace('--','-')

def package_card(p, index):
    tags = [p['language'],p['quality']]
    channel_list = ''.join(f'<li>{e(ch)}</li>' for ch in p['channels'])
    source = f'<a href="assets/documents/package-guide.pdf#page={p["page"]}" target="_blank" rel="noopener">PDF · page {p["page"]}</a>' if p['source']=='PDF' else '<a href="assets/documents/special-packs.jpeg" target="_blank" rel="noopener">Special-pack guide</a>'
    return f'''<article class="package-card" id="{slug(p['name'])}" data-package-index="{index}" data-language="{e(p['language'])}" data-quality="{e(p['quality'])}"><div class="pack-top"><span class="pill">{e(p['quality'])}</span><span>{e(p['language'])}</span></div><h2>{e(p['name'])}</h2><div class="pack-price">₹{p['price']:g}<span>{'+ tax' if p['source']=='Image' else 'incl. tax / LCO'}</span></div><p class="rate-note">{e(p['rate'])}</p><p class="pack-summary">{e(', '.join(p['channels'][:5]))} and more.</p><div class="pack-meta">{len(p['channels'])} listed channel names{' · 200+ FTA noted in PDF' if p['fta'] else ''}</div><details><summary>Explore channel line-up <span>+</span></summary><div class="channel-list-wrap"><ul class="channel-list">{channel_list}</ul></div><p class="small source-link">Source: {source}</p></details>{button('Enquire about this pack','contact.html?service=Cable%20TV&package='+p['name'].replace(' ','%20'),'dark')}</article>'''

